from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    frequency = parts[0]
    interval = int(parts[1])
    weekdays = {code: i for i, code in enumerate(
        ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
    )}

    if frequency == "DAILY":
        return [
            (first + timedelta(days=i * interval)).isoformat()
            for i in range(count)
        ]

    if frequency == "WEEKLY":
        selected = sorted(weekdays[code] for code in parts[2].split(","))
        week_start = first - timedelta(days=first.weekday())
    elif frequency == "MONTHLY":
        initial_month = first.year * 12 + first.month - 1
        number = int(parts[2])
        weekday = weekdays[parts[3]] if len(parts) == 4 else None
    else:
        month, day = map(int, parts[2].split("-"))

    result = []
    period = 0

    while True:
        candidates = []

        if frequency == "WEEKLY":
            active_week = week_start + timedelta(weeks=period * interval)
            candidates = [
                active_week + timedelta(days=wd) for wd in selected
            ]

        elif frequency == "MONTHLY":
            month_index = initial_month + period * interval
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            last_day = monthrange(year, month)[1]

            if weekday is None:
                day = last_day if number == -1 else number
            elif number == -1:
                last_weekday = date(year, month, last_day).weekday()
                day = last_day - (last_weekday - weekday) % 7
            else:
                first_weekday = date(year, month, 1).weekday()
                day = 1 + (weekday - first_weekday) % 7 + 7 * (number - 1)

            if 1 <= day <= last_day:
                candidates = [date(year, month, day)]

        else:  # YEARLY
            year = first.year + period * interval
            if day <= monthrange(year, month)[1]:
                candidates = [date(year, month, day)]

        for candidate in candidates:
            if candidate >= first:
                result.append(candidate.isoformat())
                if len(result) == count:
                    return result

        period += 1
